/**
 * @fileoverview Subtitle and Video Context Manager (`subtitle-manager.js`)
 *
 * Responsibilities:
 * 1. Detect available YouTube caption tracks via the page bridge (or preloaded cues).
 * 2. Prefer human-created captions over auto-generated (`kind !== 'asr'`) while supporting ASR seamlessly.
 * 3. Fetch and parse subtitles in both `json3` and `xml` timedtext formats with exact start/end timestamps.
 * 4. Group granular caption cues into coherent, sentence-aligned semantic chunks:
 *    - When YouTube chapters are present, splits chunks strictly at chapter boundaries (`cue.end` within 1s of `chapter.end`).
 *    - When no chapters are present, splits at natural linguistic sentence boundaries / transitions
 *      around `targetChunkSeconds`.
 * 5. Emit structured `[Breakpoint]` diagnostic logs.
 */

import { db } from '../storage/database.js';

export class SubtitleManager {
  // Static state for rate-limiting and circuit breaker across all instances
  static cooldownUntil = 0;
  static lastRequestTime = 0;
  // Use 10ms throttle in test environment (Node.js) and 1200ms throttle in browser to prevent YouTube blocks
  static MIN_REQUEST_INTERVAL_MS = (typeof window === 'undefined' && typeof process !== 'undefined' && !process.env.YT_LEARN_FORCE_THROTTLE) ? 10 : 1200;

  static resetRateLimitState() {
    SubtitleManager.cooldownUntil = 0;
    SubtitleManager.lastRequestTime = 0;
  }

  /**
   * @param {(action: string, payload: object) => Promise<any>} sendBackgroundRequest
   * @param {(msg: string) => void} [logger]
   * @param {(url: string) => Promise<any>} [sendBridgeRequest]
   */
  constructor(sendBackgroundRequest, logger = console.log, sendBridgeRequest = null) {
    this.sendBackgroundRequest = sendBackgroundRequest;
    this.log = logger;
    this.sendBridgeRequest = sendBridgeRequest;
    this.currentVideoId = null;
    this.cues = [];
    this.chunks = [];
    this.selectedTrack = null;
    this.hasSubtitles = false;

    // Dual Subtitle State
    this.availableTracks = [];
    this.primaryCues = [];
    this.secondaryCues = [];
    this.primaryTrack = null;
    this.secondaryTrack = null;
    this.hasSecondarySubtitles = false;

    // In-memory cache & deduplication to prevent server block
    this.trackCache = new Map();
    this.failedUrls = new Set();
    this.failedLanguages = new Map();
    this.inFlightRequests = new Map();
    this.localServerOfflineUntil = 0;
  }

  async loadSubtitlesForVideo(metadata, preferredLang = 'auto', preferredSecondaryLang = 'en', options = {}) {
    const {
      videoId,
      captionTracks = [],
      chapters = [],
      preloadedCues = null,
      secondaryPreloadedCues = null,
      targetChunkSeconds = 30
    } = metadata;
    this.currentVideoId = videoId;
    this.availableTracks = captionTracks || [];
    this.primaryCues = [];
    this.secondaryCues = [];
    this.hasSecondarySubtitles = false;

    if (Array.isArray(preloadedCues) && preloadedCues.length > 0) {
      this.cues = SubtitleManager.cleanAndMergeCues(preloadedCues);
      this.primaryCues = this.cues;
      this.chunks = SubtitleManager.buildSemanticChunks(
        this.cues,
        chapters,
        targetChunkSeconds
      );
      this.selectedTrack = { languageCode: preferredLang, name: 'Preloaded', isAutoGenerated: false };
      this.primaryTrack = this.selectedTrack;
      this.hasSubtitles = true;
      this.log(`[Breakpoint] Subtitles loaded: ${this.cues.length} entries`);

      if (Array.isArray(secondaryPreloadedCues) && secondaryPreloadedCues.length > 0) {
        this.secondaryCues = SubtitleManager.cleanAndMergeCues(secondaryPreloadedCues);
        this.secondaryTrack = { languageCode: preferredSecondaryLang, name: 'Secondary Preloaded', isAutoGenerated: false };
        this.hasSecondarySubtitles = true;
      }

      return {
        hasSubtitles: true,
        cues: this.cues,
        chunks: this.chunks,
        trackInfo: this.selectedTrack,
        primaryCues: this.primaryCues,
        secondaryCues: this.secondaryCues,
        secondaryTrack: this.secondaryTrack,
        availableTracks: this.availableTracks
      };
    }

    // Dual subtitle is downloaded ONLY on user demand
    const demandSecondary = (options?.enableDualSubtitles !== false) &&
      preferredSecondaryLang &&
      preferredSecondaryLang !== 'none';

    const cached = await db.getTranscript(videoId);
    if (cached && Array.isArray(cached.cues) && cached.cues.length > 0) {
      this.cues = cached.cues;
      this.primaryCues = cached.primaryCues || [];
      this.secondaryCues = (cached.secondaryCues && cached.secondaryCues.length > 0)
        ? cached.secondaryCues
        : (cached.cues || []);
      this.chunks = SubtitleManager.buildSemanticChunks(
        this.cues,
        chapters,
        targetChunkSeconds
      );
      this.selectedTrack = cached.trackInfo;
      this.primaryTrack = cached.primaryTrack || cached.trackInfo;
      this.secondaryTrack = cached.secondaryTrack || null;
      this.hasSubtitles = true;
      this.hasSecondarySubtitles = this.secondaryCues.length > 0;
      this.log(`[Breakpoint] Subtitles loaded: ${this.cues.length} entries (from cache)`);

      if (
        demandSecondary &&
        (!this.hasSecondarySubtitles || (this.secondaryTrack && this.secondaryTrack.languageCode !== preferredSecondaryLang))
      ) {
        const liveTracks = (this.availableTracks && this.availableTracks.length > 0)
          ? this.availableTracks
          : (metadata?.captionTracks || []);
        const loaded = await this.downloadSecondaryTrackOnDemand(preferredSecondaryLang, {
          captionTracks: liveTracks,
          videoId,
          ...metadata
        });
        if (loaded) {
          await db.saveTranscript(videoId, {
            cues: this.cues,
            chunks: this.chunks,
            trackInfo: this.selectedTrack,
            primaryCues: this.primaryCues,
            secondaryCues: this.secondaryCues,
            primaryTrack: this.primaryTrack,
            secondaryTrack: this.secondaryTrack
          }).catch(() => {});
        }
      }

      return {
        hasSubtitles: true,
        cues: this.cues,
        chunks: this.chunks,
        trackInfo: this.selectedTrack,
        primaryCues: this.primaryCues,
        secondaryCues: this.secondaryCues,
        secondaryTrack: this.secondaryTrack,
        availableTracks: this.availableTracks
      };
    }

    let tracks = Array.isArray(captionTracks) && captionTracks.length > 0 ? captionTracks : [];
    this.availableTracks = tracks;

    const bestTrack = SubtitleManager.selectBestTrack(tracks, preferredLang);
    this.selectedTrack = bestTrack ? {
      languageCode: bestTrack.languageCode,
      name: bestTrack.name,
      isAutoGenerated: bestTrack.kind === 'asr',
      baseUrl: bestTrack.baseUrl
    } : null;
    this.primaryTrack = this.selectedTrack;
    this.primaryCues = [];

    // The script only downloads 1 subtitle on user demand.
    // The original one will be handled natively by YouTube.
    if (demandSecondary) {
      await this.downloadSecondaryTrackOnDemand(preferredSecondaryLang, {
        captionTracks: this.availableTracks,
        videoId,
        ...metadata
      });
    }

    if (this.secondaryCues && this.secondaryCues.length > 0) {
      this.cues = this.secondaryCues;
      this.chunks = SubtitleManager.buildSemanticChunks(
        this.cues,
        chapters,
        targetChunkSeconds
      );
      this.hasSubtitles = true;
      this.log(`[Breakpoint] Subtitles loaded (1 on-demand companion track): ${this.secondaryCues.length} entries`);
    } else {
      this.cues = [];
      this.chunks = SubtitleManager.buildChapterOnlyChunks(chapters, metadata.lengthSeconds);
      this.hasSubtitles = false;
      this.log(`[Breakpoint] Subtitles loaded: 0 entries (native YouTube handles original subtitle)`);
    }

    if (this.currentVideoId && (this.cues.length > 0 || this.secondaryCues.length > 0)) {
      await db.saveTranscript(this.currentVideoId, {
        cues: this.cues,
        chunks: this.chunks,
        trackInfo: this.selectedTrack,
        primaryCues: this.primaryCues,
        secondaryCues: this.secondaryCues,
        primaryTrack: this.primaryTrack,
        secondaryTrack: this.secondaryTrack
      }).catch(() => {});
    }

    return {
      hasSubtitles: this.hasSubtitles,
      cues: this.cues,
      chunks: this.chunks,
      trackInfo: this.selectedTrack,
      primaryCues: this.primaryCues,
      secondaryCues: this.secondaryCues,
      secondaryTrack: this.secondaryTrack,
      availableTracks: this.availableTracks
    };
  }

  /**
   * Loads or switches the primary caption track dynamically.
   */
  async loadPrimaryTrack(captionTracks = [], preferredLang = 'auto', metadata = {}) {
    const tracks = Array.isArray(captionTracks) && captionTracks.length > 0
      ? captionTracks
      : this.availableTracks;
    const bestTrack = SubtitleManager.selectBestTrack(tracks, preferredLang);
    if (!bestTrack || !bestTrack.baseUrl) return false;

    this.selectedTrack = {
      languageCode: bestTrack.languageCode,
      name: bestTrack.name,
      isAutoGenerated: bestTrack.kind === 'asr',
      baseUrl: bestTrack.baseUrl
    };
    this.primaryTrack = this.selectedTrack;

    try {
      const rawCues = await this.fetchAndParseTrack(bestTrack.baseUrl);
      if (rawCues && rawCues.length > 0) {
        this.cues = SubtitleManager.cleanAndMergeCues(rawCues);
        this.primaryCues = this.cues;
        this.chunks = SubtitleManager.buildSemanticChunks(
          this.cues,
          metadata.chapters || [],
          metadata.targetChunkSeconds || 30
        );
        this.hasSubtitles = true;
        this.log(`[Breakpoint] Primary subtitle track reloaded: ${this.cues.length} entries (${bestTrack.languageCode})`);

        if (this.currentVideoId) {
          await db.saveTranscript(this.currentVideoId, {
            cues: this.cues,
            chunks: this.chunks,
            trackInfo: this.selectedTrack,
            primaryCues: this.primaryCues,
            secondaryCues: this.secondaryCues,
            primaryTrack: this.primaryTrack,
            secondaryTrack: this.secondaryTrack
          });
        }
        return true;
      }
    } catch (err) {
      console.warn('[YT-Learn SubtitleManager] Failed to reload primary track:', err.message);
    }
    return false;
  }

  /**
   * Downloads the secondary / companion subtitle track on demand for the specified language.
   * Can be invoked when the user selects a secondary language or enables companion subtitles.
   *
   * @param {string} targetLang - Language code (e.g. 'en', 'es', 'de', 'vi')
   * @param {object} [metadata] - Optional video metadata (captionTracks, videoId, etc.)
   * @returns {Promise<boolean>} Whether download succeeded
   */
  async downloadSecondaryTrackOnDemand(targetLang = 'en', metadata = {}) {
    if (!targetLang || targetLang === 'none') {
      this.secondaryCues = [];
      this.secondaryTrack = null;
      this.hasSecondarySubtitles = false;
      return false;
    }

    const videoId = metadata?.videoId || this.currentVideoId;
    if (!videoId) return false;

    // 1. In-memory track cache hit (0 network requests)
    const cacheKey = `${videoId}_${targetLang.toLowerCase()}`;
    if (this.trackCache.has(cacheKey)) {
      this.secondaryCues = this.trackCache.get(cacheKey);
      this.secondaryTrack = this.trackCache.get(`${cacheKey}_track`) || {
        languageCode: targetLang,
        name: `Sub (${targetLang.toUpperCase()})`,
        isAutoGenerated: false,
        isTranslated: false
      };
      this.hasSecondarySubtitles = this.secondaryCues.length > 0;
      return this.hasSecondarySubtitles;
    }

    // 2. FIRST PRIORITY: Query Local Subtitle Server running in terminal!
    // Downloads via terminal yt-dlp or serves from ./subtitles_cache/
    // ZERO YouTube requests from browser, 100% immune to 429 server blocks!
    let localResult = null;
    const isServerBackingOff = Date.now() < (this.localServerOfflineUntil || 0);
    if (!isServerBackingOff && typeof this.sendBackgroundRequest === 'function') {
      try {
        localResult = await this.sendBackgroundRequest('FETCH_LOCAL_SUBTITLE', {
          videoId,
          lang: targetLang
        });
        if (localResult && localResult.ok && localResult.data && Array.isArray(localResult.data.cues) && localResult.data.cues.length > 0) {
          this.secondaryCues = SubtitleManager.cleanAndMergeCues(localResult.data.cues);
          this.secondaryTrack = {
            languageCode: targetLang,
            name: localResult.data.trackInfo?.name || `Local Sub (${targetLang.toUpperCase()})`,
            isAutoGenerated: false,
            isTranslated: false,
            isLocalServer: true
          };
          this.hasSecondarySubtitles = true;
          this.failedLanguages.delete?.(cacheKey);
          this.trackCache.set(cacheKey, this.secondaryCues);
          this.trackCache.set(`${cacheKey}_track`, this.secondaryTrack);
          this.log(`[SubtitleManager] Secondary subtitle loaded from local terminal server: ${this.secondaryCues.length} entries (${targetLang})`);

          if (!this.cues || this.cues.length === 0) {
            this.cues = this.secondaryCues;
            this.chunks = SubtitleManager.buildSemanticChunks(
              this.cues,
              metadata?.chapters || [],
              metadata?.targetChunkSeconds || 30
            );
            this.hasSubtitles = true;
          }

          if (this.currentVideoId) {
            await db.saveTranscript(this.currentVideoId, {
              cues: this.cues,
              chunks: this.chunks,
              trackInfo: this.selectedTrack,
              primaryCues: this.primaryCues,
              secondaryCues: this.secondaryCues,
              primaryTrack: this.primaryTrack,
              secondaryTrack: this.secondaryTrack
            }).catch(() => {});
          }
          return true;
        } else if (localResult && (localResult.status === 404 || String(localResult.error).includes('404'))) {
          // Negative cache for 60s when local server confirms subtitle doesn't exist
          this.failedLanguages.set(cacheKey, Date.now() + 60000);
          this.log(`[SubtitleManager] Subtitle not found on local server (404) for ${videoId} (${targetLang}).`);
        } else if (localResult && (localResult.isServerOffline || localResult.error)) {
          this.localServerOfflineUntil = Date.now() + 15000;
          this.log(`[SubtitleManager] Local subtitle server unavailable (${localResult.error || 'offline'}). Seamless fallback to browser tracks.`);
        }
      } catch (localErr) {
        this.localServerOfflineUntil = Date.now() + 15000;
        this.log(`[SubtitleManager] Local server connection failed: ${localErr.message}. Seamless fallback to browser tracks.`);
      }
    }

    let tracks = (Array.isArray(metadata?.captionTracks) && metadata.captionTracks.length > 0)
      ? metadata.captionTracks
      : (Array.isArray(this.availableTracks) && this.availableTracks.length > 0)
      ? this.availableTracks
      : [];

    if (!tracks.some((t) => Boolean(t.baseUrl)) && !metadata?.activeTimedtextBaseUrl) {
      // Never synthesize fake timedtext URLs (https://www.youtube.com/api/timedtext?v=...)
      // Unsigned timedtext calls are rejected by YouTube with HTTP 429 server blocks!
      this.failedLanguages.set(cacheKey, Date.now() + 60000);
      return false;
    }

    // If local server returned 404, only look for direct tracks in available tracks, avoiding synthetic &tlang= 429s
    const allowAutoTranslate = !(localResult && (localResult.status === 404 || String(localResult.error).includes('404')));
    return await this.loadSecondaryTrack(tracks, targetLang, this.primaryTrack || this.selectedTrack, metadata, allowAutoTranslate);
  }

  /**
   * Retrieves only the active secondary / companion cue at `currentTime`.
   */
  getActiveSecondaryCue(currentTime = 0) {
    const cue = SubtitleManager.findActiveCue(this.secondaryCues, currentTime);
    return cue ? cue.text.trim() : '';
  }

  /**
   * Loads the secondary caption track for Dual Subtitles.
   * Checks for a direct matching track in captionTracks first, or uses YouTube's
   * &tlang= timedtext parameter to automatically translate from the primary track.
   */
  async loadSecondaryTrack(captionTracks = [], preferredSecondaryLang = 'en', primaryTrack = null, metadata = {}, allowAutoTranslate = true) {
    if (!preferredSecondaryLang || preferredSecondaryLang === 'none') {
      this.secondaryCues = [];
      this.secondaryTrack = null;
      this.hasSecondarySubtitles = false;
      return false;
    }

    if (Array.isArray(metadata?.secondaryPreloadedCues) && metadata.secondaryPreloadedCues.length > 0) {
      this.secondaryCues = SubtitleManager.cleanAndMergeCues(metadata.secondaryPreloadedCues);
      this.secondaryTrack = {
        languageCode: preferredSecondaryLang,
        name: 'Preloaded Translation',
        isAutoGenerated: false,
        isTranslated: false
      };
      this.hasSecondarySubtitles = true;
      return true;
    }

    const vid = metadata?.videoId || this.currentVideoId;
    const cacheKey = `${vid || 'curr'}_${preferredSecondaryLang.toLowerCase()}`;

    // 1. In-memory cache hit: 0 network requests!
    if (this.trackCache.has(cacheKey)) {
      this.secondaryCues = this.trackCache.get(cacheKey);
      this.secondaryTrack = this.trackCache.get(`${cacheKey}_track`) || {
        languageCode: preferredSecondaryLang,
        name: preferredSecondaryLang.toUpperCase(),
        isAutoGenerated: false,
        isTranslated: false
      };
      this.hasSecondarySubtitles = this.secondaryCues.length > 0;
      return this.hasSecondarySubtitles;
    }

    const failedUntil = this.failedLanguages.get?.(cacheKey) || (this.failedLanguages.has?.(cacheKey) ? Infinity : 0);
    if (failedUntil && Date.now() < failedUntil) {
      return false;
    }

    const tracks = Array.isArray(captionTracks) && captionTracks.length > 0
      ? captionTracks
      : this.availableTracks;

    const targetPrefix = preferredSecondaryLang.toLowerCase().split('-')[0];
    const primaryCode = (primaryTrack?.languageCode || this.primaryTrack?.languageCode || '').toLowerCase();

    // 2. Direct matching track in captionTracks
    const directTrack = (tracks || []).find((t) => {
      const code = (t.languageCode || '').toLowerCase();
      return (
        (code === preferredSecondaryLang.toLowerCase() || code.startsWith(targetPrefix)) &&
        t.baseUrl
      );
    });

    if (directTrack && directTrack.baseUrl) {
      try {
        const rawCues = await this.fetchAndParseTrack(directTrack.baseUrl);
        if (rawCues && rawCues.length > 0) {
          this.secondaryCues = SubtitleManager.cleanAndMergeCues(rawCues);
          this.secondaryTrack = {
            languageCode: directTrack.languageCode,
            name: directTrack.name || directTrack.languageCode,
            isAutoGenerated: directTrack.kind === 'asr',
            isTranslated: false
          };
          this.hasSecondarySubtitles = true;
          this.failedLanguages.delete?.(cacheKey);
          this.trackCache.set(cacheKey, this.secondaryCues);
          this.trackCache.set(`${cacheKey}_track`, this.secondaryTrack);
          this.log(`[Breakpoint] Secondary caption track loaded: ${this.secondaryCues.length} entries (${directTrack.languageCode})`);

          if (!this.cues || this.cues.length === 0) {
            this.cues = this.secondaryCues;
            this.chunks = SubtitleManager.buildSemanticChunks(
              this.cues,
              metadata?.chapters || [],
              metadata?.targetChunkSeconds || 30
            );
            this.hasSubtitles = true;
          }

          if (this.currentVideoId) {
            await db.saveTranscript(this.currentVideoId, {
              cues: this.cues,
              chunks: this.chunks,
              trackInfo: this.selectedTrack,
              primaryCues: this.primaryCues,
              secondaryCues: this.secondaryCues,
              primaryTrack: this.primaryTrack,
              secondaryTrack: this.secondaryTrack
            }).catch(() => {});
          }
          return true;
        }
      } catch (err) {
        console.warn('[YT-Learn SubtitleManager] Direct secondary track fetch failed:', err.message);
      }
    }

    // 3. Auto-translation via YouTube &tlang= parameter
    if (allowAutoTranslate) {
      const sourceTrack = primaryTrack?.baseUrl
        ? primaryTrack
        : this.primaryTrack?.baseUrl
        ? this.primaryTrack
        : (tracks || []).find((t) => t.baseUrl) ||
          (metadata?.activeTimedtextBaseUrl ? { baseUrl: metadata.activeTimedtextBaseUrl } : null);

      if (sourceTrack && sourceTrack.baseUrl) {
        const effectiveSecondaryLang = preferredSecondaryLang;
        let base = SubtitleManager.normalizeTimedtextUrl(sourceTrack.baseUrl);
        // Strip any prior tlang or fmt=json3 to let YouTube return clean translation XML/srv3
        base = base.replace(/[?&]tlang=[^&]+/, '').replace(/[?&]fmt=json3/, '');
        const targetLang = encodeURIComponent(effectiveSecondaryLang);
        const translatedUrl = `${base}${base.includes('?') ? '&' : '?'}tlang=${targetLang}`;

        try {
          const rawTranslated = await this.fetchAndParseTrack(translatedUrl);
          if (rawTranslated && rawTranslated.length > 0) {
            this.secondaryCues = SubtitleManager.cleanAndMergeCues(rawTranslated);
            this.secondaryTrack = {
              languageCode: effectiveSecondaryLang,
              name: `Translated (${effectiveSecondaryLang.toUpperCase()})`,
              isAutoGenerated: true,
              isTranslated: true
            };
            this.hasSecondarySubtitles = true;
            this.failedLanguages.delete?.(cacheKey);
            this.trackCache.set(cacheKey, this.secondaryCues);
            this.trackCache.set(`${cacheKey}_track`, this.secondaryTrack);
            this.log(`[Breakpoint] Secondary auto-translated captions loaded: ${this.secondaryCues.length} entries (${effectiveSecondaryLang})`);

            if (!this.cues || this.cues.length === 0) {
              this.cues = this.secondaryCues;
              this.chunks = SubtitleManager.buildSemanticChunks(
                this.cues,
                metadata?.chapters || [],
                metadata?.targetChunkSeconds || 30
              );
              this.hasSubtitles = true;
            }

            if (this.currentVideoId) {
              await db.saveTranscript(this.currentVideoId, {
                cues: this.cues,
                chunks: this.chunks,
                trackInfo: this.selectedTrack,
                primaryCues: this.primaryCues,
                secondaryCues: this.secondaryCues,
                primaryTrack: this.primaryTrack,
                secondaryTrack: this.secondaryTrack
              }).catch(() => {});
            }
            return true;
          }
        } catch (err) {
          console.warn('[YT-Learn SubtitleManager] Auto-translated caption fetch failed:', err.message);
        }
      }
    }

    this.failedLanguages.set(cacheKey, Date.now() + 60000);
    this.secondaryCues = [];
    this.secondaryTrack = null;
    this.hasSecondarySubtitles = false;
    return false;
  }

  /**
   * Fast O(log N) binary search lookup with neighbor window checking for active cues.
   */
  static findActiveCue(cues = [], currentTime = 0) {
    if (!Array.isArray(cues) || cues.length === 0) return null;
    let low = 0;
    let high = cues.length - 1;
    let candidateIdx = -1;

    while (low <= high) {
      const mid = (low + high) >> 1;
      if (cues[mid].start <= currentTime) {
        candidateIdx = mid;
        low = mid + 1;
      } else {
        high = mid - 1;
      }
    }

    if (candidateIdx >= 0) {
      for (let i = candidateIdx; i >= Math.max(0, candidateIdx - 2); i--) {
        const cue = cues[i];
        if (currentTime >= cue.start && currentTime <= cue.end + 0.35) {
          return cue;
        }
      }
    }
    return null;
  }

  /**
   * Retrieves the currently active dual subtitles (primary + secondary) at `currentTime`.
   */
  getActiveDualCues(currentTime = 0) {
    const primaryCue = this.primaryCues && this.primaryCues.length > 0
      ? SubtitleManager.findActiveCue(this.primaryCues, currentTime)
      : null;
    const secondarySource = (this.secondaryCues && this.secondaryCues.length > 0)
      ? this.secondaryCues
      : (this.cues && this.cues.length > 0 ? this.cues : []);
    const secondaryCue = SubtitleManager.findActiveCue(secondarySource, currentTime);

    let primaryText = primaryCue ? primaryCue.text.trim() : '';
    let secondaryText = secondaryCue ? secondaryCue.text.trim() : '';

    // Live DOM fallback: Since YouTube natively handles the original subtitle on the player,
    // read the live caption segment from YouTube's player if primaryText is not preloaded!
    if (!primaryText && typeof document !== 'undefined' && typeof document.querySelectorAll === 'function') {
      const liveNativeSegments = document.querySelectorAll(
        '#movie_player .ytp-caption-segment, .ytp-caption-window-bottom .ytp-caption-segment'
      );
      if (liveNativeSegments.length > 0) {
        primaryText = Array.from(liveNativeSegments)
          .map((el) => el.textContent)
          .join(' ')
          .replace(/\s+/g, ' ')
          .trim();
      }
    }

    // Only suppress secondaryText if primaryText is non-empty and identical to secondaryText
    // when BOTH were loaded internally by SubtitleManager (i.e. this.primaryCues.length > 0)
    const isInternalDuplicate = Boolean(
      this.primaryCues &&
      this.primaryCues.length > 0 &&
      primaryText &&
      secondaryText &&
      primaryText.toLowerCase() === secondaryText.toLowerCase()
    );

    return {
      primaryText,
      secondaryText: isInternalDuplicate ? '' : secondaryText,
      primaryCue,
      secondaryCue,
      hasActiveText: Boolean(secondaryText || primaryText)
    };
  }

  static buildChapterOnlyChunks(chapters = [], videoDuration = 0) {
    if (!Array.isArray(chapters) || chapters.length === 0) return [];
    return chapters
      .filter((ch) => typeof ch.end === 'number' && ch.end > ch.start)
      .map((ch, idx) => ({
        id: `chunk_${idx}`,
        index: idx,
        start: Number(ch.start.toFixed(2)),
        end: Number(ch.end.toFixed(2)),
        chapterTitle: ch.title || `Chapter ${idx + 1}`,
        text: `In "${ch.title || `Chapter ${idx + 1}`}", the instructor explains the key concepts and practical details of this topic.`,
        cues: [
          {
            start: Number(ch.start.toFixed(2)),
            end: Number(ch.end.toFixed(2)),
            text: `In "${ch.title || `Chapter ${idx + 1}`}", the instructor explains the key concepts and practical details of this topic.`
          }
        ],
        isChapterBoundary: !videoDuration || ch.end < videoDuration - 0.5
      }));
  }

  static selectBestTrack(tracks = [], preferredLang = 'auto') {
    if (!Array.isArray(tracks) || tracks.length === 0) return null;
    if (!preferredLang || preferredLang === 'auto') {
      const anyHuman = tracks.find((t) => t.kind !== 'asr');
      return anyHuman || tracks[0];
    }
    const langPrefix = preferredLang.toLowerCase().split('-')[0];

    const humanPreferred = tracks.find(
      (t) => t.kind !== 'asr' && t.languageCode?.toLowerCase().startsWith(langPrefix)
    );
    if (humanPreferred) return humanPreferred;

    const asrPreferred = tracks.find(
      (t) => t.kind === 'asr' && t.languageCode?.toLowerCase().startsWith(langPrefix)
    );
    if (asrPreferred) return asrPreferred;

    const anyHuman = tracks.find((t) => t.kind !== 'asr');
    return anyHuman || tracks[0];
  }

  static normalizeTimedtextUrl(url) {
    if (!url) return '';
    let normalized = String(url).trim();
    if (normalized.startsWith('//')) {
      normalized = 'https:' + normalized;
    } else if (normalized.startsWith('/')) {
      normalized = 'https://www.youtube.com' + normalized;
    }
    return normalized;
  }

  async fetchAndParseTrack(rawUrl) {
    const baseUrl = SubtitleManager.normalizeTimedtextUrl(rawUrl);
    if (!baseUrl) return [];

    // 1. Circuit breaker: if server previously blocked / rate-limited (HTTP 429/403), stop immediately!
    if (Date.now() < SubtitleManager.cooldownUntil) {
      const remainingSec = Math.ceil((SubtitleManager.cooldownUntil - Date.now()) / 1000);
      this.log(`[SubtitleManager] Timedtext rate-limit cooldown active (${remainingSec}s remaining). Fetch blocked.`);
      return [];
    }

    // 2. Negative cache: do not re-request URLs that already failed or 404'd
    if (this.failedUrls && this.failedUrls.has(baseUrl)) {
      return [];
    }

    // 3. In-memory cache hit: 0 network requests!
    if (this.trackCache && this.trackCache.has(baseUrl)) {
      return this.trackCache.get(baseUrl);
    }

    // 4. In-flight request deduplication: return existing pending promise
    if (this.inFlightRequests && this.inFlightRequests.has(baseUrl)) {
      return await this.inFlightRequests.get(baseUrl);
    }

    const requestPromise = (async () => {
      try {
        // Enforce safe spacing between timedtext network calls to prevent triggering server block
        const now = Date.now();
        const timeSinceLast = now - SubtitleManager.lastRequestTime;
        if (timeSinceLast < SubtitleManager.MIN_REQUEST_INTERVAL_MS) {
          const delay = SubtitleManager.MIN_REQUEST_INTERVAL_MS - timeSinceLast;
          await new Promise((resolve) => setTimeout(resolve, delay));
        }
        SubtitleManager.lastRequestTime = Date.now();

        const isTranslated = baseUrl.includes('tlang=');
        let rawContent = '';
        let targetUrl = baseUrl;

        // Auto-translation timedtext must not include fmt=json3 (YouTube requires XML/srv3 for tlang)
        if (isTranslated) {
          targetUrl = baseUrl.replace(/[?&]fmt=json3/, '');
        }

        // Channel 1: Bridge request (runs in YouTube main page world with native credentials)
        let bridgeResponse = null;
        if (this.sendBridgeRequest) {
          try {
            bridgeResponse = await this.sendBridgeRequest(targetUrl);
          } catch (err) {}
        }

        if (bridgeResponse) {
          if (bridgeResponse.status === 429 || bridgeResponse.status === 403) {
            SubtitleManager.cooldownUntil = Date.now() + 60000;
            this.failedUrls.add(baseUrl);
            this.log(`[SubtitleManager] YouTube rate limit reached (HTTP ${bridgeResponse.status}). Cooldown activated for 60s.`);
            return [];
          }
          if (bridgeResponse.status === 404) {
            this.failedUrls.add(baseUrl);
            return [];
          }
          if (bridgeResponse.ok && bridgeResponse.data) {
            rawContent = String(bridgeResponse.data).trim();
          }
        }

        // Channel 2: Background script fallback (runs via extension service worker with host permissions)
        if (!rawContent && !(bridgeResponse && (bridgeResponse.status === 429 || bridgeResponse.status === 403))) {
          try {
            const bgRes = await this.sendBackgroundRequest('FETCH_CAPTION_TRACK', { url: targetUrl });
            if (bgRes) {
              if (bgRes.status === 429 || bgRes.status === 403 || String(bgRes.error).includes('429')) {
                SubtitleManager.cooldownUntil = Date.now() + 60000;
                this.failedUrls.add(baseUrl);
                this.log(`[SubtitleManager] YouTube rate limit reached in background. Cooldown activated for 60s.`);
                return [];
              }
              if (bgRes.status === 404) {
                this.failedUrls.add(baseUrl);
                return [];
              }
              if (bgRes.ok && bgRes.data) {
                rawContent = String(bgRes.data).trim();
              }
            }
          } catch (bgErr) {}
        }

        if (!rawContent) {
          return [];
        }

        let parsed = [];
        if (rawContent.startsWith('{')) {
          parsed = SubtitleManager.parseJson3Captions(rawContent);
        } else if (rawContent.includes('<transcript') || rawContent.includes('<timedtext') || rawContent.includes('<p ') || rawContent.includes('<text ')) {
          parsed = SubtitleManager.parseXmlCaptions(rawContent);
        } else if (rawContent.includes('WEBVTT') || rawContent.includes('-->')) {
          parsed = SubtitleManager.parseVttCaptions(rawContent);
        } else {
          parsed = SubtitleManager.parseXmlCaptions(rawContent);
        }

        if (parsed.length > 0) {
          this.trackCache.set(baseUrl, parsed);
          return parsed;
        }

        return [];
      } finally {
        this.inFlightRequests.delete(baseUrl);
      }
    })();

    this.inFlightRequests.set(baseUrl, requestPromise);
    return await requestPromise;
  }

  static parseVttCaptions(vttString) {
    if (!vttString || !vttString.includes('-->')) return [];
    const cues = [];
    const lines = vttString.split('\n');
    let currentStart = null;
    let currentEnd = null;
    let currentText = [];

    const timeRegex = /(?:(\d{1,2}):)?(\d{2}):(\d{2})[.,](\d{3})\s*-->\s*(?:(\d{1,2}):)?(\d{2}):(\d{2})[.,](\d{3})/;

    const parseSec = (hh, mm, ss, ms) => {
      const h = hh ? parseInt(hh, 10) : 0;
      const m = parseInt(mm, 10);
      const s = parseInt(ss, 10);
      const millis = parseInt(ms, 10);
      return h * 3600 + m * 60 + s + millis / 1000;
    };

    for (const rawLine of lines) {
      const line = rawLine.trim();
      const match = line.match(timeRegex);
      if (match) {
        if (currentStart !== null && currentText.length > 0) {
          const text = SubtitleManager.cleanSubtitleText(currentText.join(' '));
          if (text) {
            cues.push({
              start: Number(currentStart.toFixed(2)),
              end: Number(currentEnd.toFixed(2)),
              text
            });
          }
          currentText = [];
        }
        currentStart = parseSec(match[1], match[2], match[3], match[4]);
        currentEnd = parseSec(match[5], match[6], match[7], match[8]);
      } else if (currentStart !== null && line && !/^\d+$/.test(line) && !line.startsWith('NOTE') && !line.startsWith('WEBVTT')) {
        currentText.push(line);
      }
    }

    if (currentStart !== null && currentText.length > 0) {
      const text = SubtitleManager.cleanSubtitleText(currentText.join(' '));
      if (text) {
        cues.push({
          start: Number(currentStart.toFixed(2)),
          end: Number(currentEnd.toFixed(2)),
          text
        });
      }
    }

    return cues;
  }

  static parseJson3Captions(jsonString) {
    try {
      const data = JSON.parse(jsonString);
      const events = data?.events || [];
      const cues = [];

      for (const ev of events) {
        if (!ev.segs || typeof ev.tStartMs !== 'number') continue;
        const text = ev.segs
          .map((s) => s.utf8 || '')
          .join('')
          .replace(/\n+/g, ' ')
          .trim();
        if (!text) continue;

        const start = ev.tStartMs / 1000;
        const duration = (ev.dDurationMs || 2500) / 1000;
        cues.push({
          start: Number(start.toFixed(2)),
          end: Number((start + duration).toFixed(2)),
          text
        });
      }
      return cues;
    } catch {
      return [];
    }
  }

  static cleanSubtitleText(rawText = '') {
    if (!rawText) return '';
    return String(rawText)
      .replace(/&amp;/g, '&')
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/&quot;/g, '"')
      .replace(/&#39;/g, "'")
      .replace(/<[^>]+>/g, '')
      .replace(/\s+/g, ' ')
      .trim();
  }

  static parseXmlCaptions(xmlString) {
    if (!xmlString) return [];
    if (typeof DOMParser !== 'undefined') {
      const parser = new DOMParser();
      const doc = parser.parseFromString(xmlString, 'text/xml');
      const nodes = Array.from(doc.querySelectorAll('text, p'));
      const cues = [];

      for (const node of nodes) {
        const startAttr = node.getAttribute('start') || node.getAttribute('t');
        const durAttr = node.getAttribute('dur') || node.getAttribute('d');
        if (startAttr === null) continue;

        const isMs = node.tagName.toLowerCase() === 'p';
        const start = isMs ? parseFloat(startAttr) / 1000 : parseFloat(startAttr);
        const dur = durAttr
          ? isMs
            ? parseFloat(durAttr) / 1000
            : parseFloat(durAttr)
          : 2.5;

        const decodedText = SubtitleManager.cleanSubtitleText(node.textContent || '');
        if (decodedText) {
          cues.push({
            start: Number(start.toFixed(2)),
            end: Number((start + dur).toFixed(2)),
            text: decodedText
          });
        }
      }
      return cues;
    }

    // Regex fallback for environments without DOMParser (e.g. Node tests / background workers)
    const cues = [];
    const pRegex = /<p\b([^>]*?)>([\s\S]*?)<\/p>/gi;
    let match;
    while ((match = pRegex.exec(xmlString)) !== null) {
      const attrs = match[1];
      const tMatch = attrs.match(/\bt="(\d+)"/i);
      if (!tMatch) continue;
      const dMatch = attrs.match(/\bd="(\d+)"/i);
      const start = parseInt(tMatch[1], 10) / 1000;
      const dur = dMatch ? parseInt(dMatch[1], 10) / 1000 : 2.5;
      const text = SubtitleManager.cleanSubtitleText(match[2]);
      if (text) {
        cues.push({
          start: Number(start.toFixed(2)),
          end: Number((start + dur).toFixed(2)),
          text
        });
      }
    }
    if (cues.length > 0) return cues;

    const textRegex = /<text\b([^>]*?)>([\s\S]*?)<\/text>/gi;
    while ((match = textRegex.exec(xmlString)) !== null) {
      const attrs = match[1];
      const startMatch = attrs.match(/\bstart="([0-9.]+)"/i);
      if (!startMatch) continue;
      const durMatch = attrs.match(/\bdur="([0-9.]+)"/i);
      const start = parseFloat(startMatch[1]);
      const dur = durMatch ? parseFloat(durMatch[1]) : 2.5;
      const text = SubtitleManager.cleanSubtitleText(match[2]);
      if (text) {
        cues.push({
          start: Number(start.toFixed(2)),
          end: Number((start + dur).toFixed(2)),
          text
        });
      }
    }
    return cues;
  }

  static cleanAndMergeCues(rawCues) {
    if (!Array.isArray(rawCues) || rawCues.length === 0) return [];
    const sorted = [...rawCues]
      .filter((c) => c && typeof c.start === 'number' && typeof c.end === 'number' && c.text)
      .sort((a, b) => a.start - b.start);

    const cleaned = [];
    for (let i = 0; i < sorted.length; i++) {
      const current = { ...sorted[i] };
      const next = sorted[i + 1];
      if (next && current.end > next.start) {
        current.end = Math.max(current.start + 0.3, Number(next.start.toFixed(2)));
      }
      if (current.text) {
        cleaned.push(current);
      }
    }
    return cleaned;
  }

  /**
   * Divides the cue list into semantic chunks:
   * - If the video has chapters (`chapters.length > 0`), splits strictly at chapter boundaries
   *   where `Math.abs(cue.end - chapterEnd) <= 1.5` or where the cue crosses `chapterEnd`.
   * - If the video has NO chapters, splits based on linguistic sentence completions,
   *   pauses, and transition phrases around `targetChunkSeconds`.
   */
  static buildSemanticChunks(cues, chapters = [], targetChunkSeconds = 30) {
    if (!cues || cues.length === 0) return [];

    const sortedChapters = [...(chapters || [])].sort((a, b) => a.start - b.start);
    const hasChapters = sortedChapters.length > 0;
    const chapterEndTimes = sortedChapters
      .map((ch) => Number(ch.end))
      .filter((t) => Number.isFinite(t) && t > 0);

    const chunks = [];
    let currentCues = [];
    let chunkStart = cues[0].start;

    for (let i = 0; i < cues.length; i++) {
      const cue = cues[i];
      const nextCue = cues[i + 1];
      currentCues.push(cue);

      const durationSoFar = cue.end - chunkStart;
      const endsWithSentence = /[.?!]["']?$/.test(cue.text.trim());
      const pauseGap = nextCue ? nextCue.start - cue.end : 2.0;

      // Exact check: does this cue end at a chapter boundary (within 1.5s) or cross a chapter boundary?
      const matchedChapterEnd = chapterEndTimes.find(
        (b) =>
          Math.abs(cue.end - b) <= 1.5 ||
          (cue.start < b && cue.end >= b) ||
          (nextCue && cue.end < b && nextCue.start >= b)
      );

      let shouldSplit = false;

      if (!nextCue || matchedChapterEnd !== undefined) {
        shouldSplit = true;
      } else if (hasChapters) {
        shouldSplit = durationSoFar >= 180 && endsWithSentence;
      } else {
        const isTransitionPhrase =
          /^(now let's|next|moving on|on the other hand|another important|in summary|finally|to understand|however)/i.test(
            nextCue.text.trim()
          );

        shouldSplit =
          (durationSoFar >= targetChunkSeconds &&
            (endsWithSentence || pauseGap >= 0.65 || isTransitionPhrase)) ||
          (durationSoFar >= 22 && isTransitionPhrase && endsWithSentence) ||
          durationSoFar >= targetChunkSeconds * 1.45;
      }

      if (shouldSplit) {
        const chunkIndex = chunks.length;
        const exactEnd =
          matchedChapterEnd !== undefined
            ? Number(matchedChapterEnd.toFixed(2))
            : Number(cue.end.toFixed(2));
        const matchedChapterObj = sortedChapters.find(
          (ch) =>
            Math.abs(ch.end - exactEnd) <= 2.0 ||
            (chunkStart >= ch.start - 1 && exactEnd <= ch.end + 1)
        );

        chunks.push({
          id: `chunk_${chunkIndex}`,
          index: chunkIndex,
          start: Number(chunkStart.toFixed(2)),
          end: exactEnd,
          chapterTitle: matchedChapterObj?.title || null,
          text: currentCues.map((c) => c.text).join(' '),
          cues: currentCues,
          isChapterBoundary: matchedChapterEnd !== undefined
        });
        currentCues = [];
        if (nextCue) {
          chunkStart = nextCue.start;
        }
      }
    }

    return chunks;
  }

  getChunkAtTime(currentTime) {
    return (
      this.chunks.find((ch) => currentTime >= ch.start && currentTime <= ch.end + 1.5) || null
    );
  }
}
